const PRODUCT_KEY = "policy_builder";

// ─── SUPABASE CLIENT (no SDK needed — raw fetch) ──────────────────────────────
const sb = {
  headers: { "apikey": SUPABASE_ANON_KEY, "Content-Type": "application/json" },
  authHeaders: (token) => ({
    "apikey": SUPABASE_ANON_KEY,
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json",
  }),
  async signUp(email, password) {
    const r = await fetch(SUPABASE_URL + "/auth/v1/signup", {
      method: "POST", headers: sb.headers,
      body: JSON.stringify({ email, password }),
    });
    return r.json();
  },
  async signIn(email, password) {
    const r = await fetch(SUPABASE_URL + "/auth/v1/token?grant_type=password", {
      method: "POST", headers: sb.headers,
      body: JSON.stringify({ email, password }),
    });
    return r.json();
  },
  async signOut(token) {
    await fetch(SUPABASE_URL + "/auth/v1/logout", {
      method: "POST", headers: sb.authHeaders(token),
    });
  },
  async resetPassword(email) {
    const r = await fetch(SUPABASE_URL + "/auth/v1/recover", {
      method: "POST", headers: sb.headers,
      body: JSON.stringify({ email }),
    });
    return r.json();
  },
  async updatePassword(token, password) {
    const r = await fetch(SUPABASE_URL + "/auth/v1/user", {
      method: "PUT", headers: sb.authHeaders(token),
      body: JSON.stringify({ password }),
    });
    return r.json();
  },
  async getUser(token) {
    const r = await fetch(SUPABASE_URL + "/auth/v1/user", {
      headers: sb.authHeaders(token),
    });
    return r.json();
  },
  async checkAccess(token, userId) {
    const r = await fetch(
      SUPABASE_URL + "/rest/v1/user_access?user_id=eq." + userId + "&product=eq." + PRODUCT_KEY + "&select=id",
      { headers: sb.authHeaders(token) }
    );
    const data = await r.json();
    return Array.isArray(data) && data.length > 0;
  },
  async getPresets(token, userId) {
    const r = await fetch(
      SUPABASE_URL + "/rest/v1/policy_presets?user_id=eq." + userId + "&order=created_at.desc",
      { headers: sb.authHeaders(token) }
    );
    return r.json();
  },
  async savePreset(token, userId, name, data) {
    const r = await fetch(SUPABASE_URL + "/rest/v1/policy_presets", {
      method: "POST",
      headers: { ...sb.authHeaders(token), "Prefer": "return=representation" },
      body: JSON.stringify({ user_id: userId, name, data }),
    });
    return r.json();
  },
  async deletePreset(token, id) {
    await fetch(SUPABASE_URL + "/rest/v1/policy_presets?id=eq." + id, {
      method: "DELETE", headers: sb.authHeaders(token),
    });
  },
};

// ─── AUTH SCREEN ──────────────────────────────────────────────────────────────
function AuthScreen({ onAuth }) {
  const [mode, setMode] = useState("login"); // login | signup | forgot | reset
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState(null); // {text, type: ok|err}

  // Check for password reset token in URL hash
  useEffect(() => {
    const hash = window.location.hash;
    if (hash.includes("type=recovery")) {
      setMode("reset");
    }
  }, []);

  // Extract access token from URL hash for password reset
  const getResetToken = () => {
    const hash = window.location.hash.substring(1);
    const params = new URLSearchParams(hash);
    return params.get("access_token");
  };

  const handle = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMsg(null);
    try {
      if (mode === "login") {
        const res = await sb.signIn(email, password);
        if (res.error) { setMsg({ text: res.error.message || "Invalid email or password.", type: "err" }); }
        else { onAuth(res.access_token, res.user); }
      } else if (mode === "signup") {
        if (password !== password2) { setMsg({ text: "Passwords do not match.", type: "err" }); setLoading(false); return; }
        const res = await sb.signUp(email, password);
        if (res.error) { setMsg({ text: res.error.message, type: "err" }); }
        else { setMsg({ text: "Account created. Please check your email to confirm, then log in.", type: "ok" }); setMode("login"); }
      } else if (mode === "forgot") {
        const res = await sb.resetPassword(email);
        if (res.error) { setMsg({ text: res.error.message, type: "err" }); }
        else { setMsg({ text: "Password reset email sent. Check your inbox.", type: "ok" }); }
      } else if (mode === "reset") {
        if (password !== password2) { setMsg({ text: "Passwords do not match.", type: "err" }); setLoading(false); return; }
        const token = getResetToken();
        const res = await sb.updatePassword(token, password);
        if (res.error) { setMsg({ text: res.error.message, type: "err" }); }
        else { setMsg({ text: "Password updated. You can now log in.", type: "ok" }); setMode("login"); window.location.hash = ""; }
      }
    } catch(err) {
      setMsg({ text: "Something went wrong. Please try again.", type: "err" });
    }
    setLoading(false);
  };

  const LOGO_SRC_AUTH = "data:image/webp;base64,";

  return (
    <div className="authWrap">
      <style>{AUTH_CSS}</style>
      <div className="authCard">
        <div className="authLogo">
          <div className="hausLockup">
            <div className="hausLockupTop">HAUS</div>
            <div className="hausLockupMiddle"><span></span><em>OF</em><span></span></div>
            <div className="hausLockupBottom">M</div>
            <div className="hausLockupSub">Beauty Business Tools</div>
          </div>
        </div>
        <h2 className="authTitle">
          {mode==="login"&&"Sign in to your account"}
          {mode==="signup"&&"Create your account"}
          {mode==="forgot"&&"Reset your password"}
          {mode==="reset"&&"Choose a new password"}
        </h2>
        {mode==="signup"&&<p className="authNote">Already purchased? Create your account below using the email you used to buy.</p>}
        <form onSubmit={handle} className="authForm">
          {(mode==="login"||mode==="signup"||mode==="forgot")&&(
            <div className="authField">
              <label>Email</label>
              <input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required autoComplete="email"/>
            </div>
          )}
          {(mode==="login"||mode==="signup"||mode==="reset")&&(
            <div className="authField">
              <label>{mode==="reset"?"New password":"Password"}</label>
              <input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" required autoComplete={mode==="login"?"current-password":"new-password"}/>
            </div>
          )}
          {(mode==="signup"||mode==="reset")&&(
            <div className="authField">
              <label>Confirm password</label>
              <input type="password" value={password2} onChange={e=>setPassword2(e.target.value)} placeholder="••••••••" required autoComplete="new-password"/>
            </div>
          )}
          {msg&&<div className={`authMsg authMsg--${msg.type}`}>{msg.text}</div>}
          <button type="submit" className="authBtn" disabled={loading}>
            {loading?"Please wait…":mode==="login"?"Sign in":mode==="signup"?"Create account":mode==="forgot"?"Send reset email":"Update password"}
          </button>
        </form>
        <div className="authLinks">
          {mode==="login"&&<><button onClick={()=>{setMode("signup");setMsg(null);}}>Create an account</button><button onClick={()=>{setMode("forgot");setMsg(null);}}>Forgot password?</button></>}
          {mode==="signup"&&<button onClick={()=>{setMode("login");setMsg(null);}}>Already have an account? Sign in</button>}
          {mode==="forgot"&&<button onClick={()=>{setMode("login");setMsg(null);}}>Back to sign in</button>}
          {mode==="reset"&&<button onClick={()=>{setMode("login");setMsg(null);}}>Back to sign in</button>}
        </div>
      </div>
    </div>
  );
}

