// ─── HELPERS ──────────────────────────────────────────────────────────────────

function money(value,currency){
  try{return new Intl.NumberFormat("en-NZ",{style:"currency",currency,maximumFractionDigits:0}).format(Number.isFinite(Number(value))?Number(value):0);}
  catch{return `$${Math.round(Number(value)||0)}`;}
}
function doClipboard(text){
  const t=String(text||"");
  const fb=()=>{const el=document.createElement("textarea");el.value=t;el.style.position="fixed";el.style.left="-9999px";document.body.appendChild(el);el.focus();el.select();document.execCommand("copy");document.body.removeChild(el);};
  if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(t).catch(fb);
  fb();return Promise.resolve();
}

function createToneContent(s,currency){
  const a=money(s.bookingFeeAmount,currency);
  const map={
    soft:{intro:`Hey lovely. Before booking with ${s.businessName}, please take a moment to read through the policies below.`,booking:`A ${a} booking fee helps secure your appointment time and preparation.`,cancellation:`If you need to make changes, please try to give at least ${s.cancellationNotice} hours' notice where possible.`,refund:"If you have any concerns after your appointment, please reach out kindly so we can review things together."},
    clear:{intro:`Please read the policies below before booking with ${s.businessName}. These help keep appointments clear, fair, and respectful of everyone's time.`,booking:`A booking fee of ${a} is required to secure your appointment. Bookings are not confirmed until payment has been received.`,cancellation:`Cancellations with less than ${s.cancellationNotice} hours' notice may result in the booking fee being retained.`,refund:"Refunds are not offered for change of mind. Service concerns must be raised within the required timeframe."},
    firm:{intro:`By booking with ${s.businessName}, you agree to the policies below. These policies protect appointment time, business costs, and professional standards.`,booking:"Appointments without a paid booking fee will not be held or confirmed.",cancellation:"Late cancellations and no-shows may result in loss of booking fees and restricted future bookings.",refund:"All services are final. Concerns raised outside the required timeframe may be treated as a new appointment."},
    premium:{intro:`At ${s.businessName}, each appointment is reserved intentionally to allow time, preparation, and a high standard of service.`,booking:`A reservation fee of ${a} is required to reserve your appointment time.`,cancellation:`Changes made within ${s.cancellationNotice} hours may result in the reservation fee being retained.`,refund:"Due to the customised nature of services, refunds are not offered for change of mind. Any concerns should be raised promptly so they can be professionally reviewed."},
  };
  return map[s.tone]||map.clear;
}

function createPolicySections(s,inc,currency){
  const sec=[];const tc=createToneContent(s,currency);const t=s.tone;
  const a=money(s.bookingFeeAmount,currency);
  const rt=`${s.rescheduleLimit} time${Number(s.rescheduleLimit)===1?"":"s"}`;
  if(inc.bookingFee)sec.push({title:"Booking Fee",text:`${tc.booking} This amount is applied toward your appointment unless stated otherwise in the cancellation or no-show policy.`,short:{soft:`A ${a} booking fee helps secure your appointment time.`,clear:`A ${a} booking fee is required to confirm your appointment.`,firm:`A ${a} booking fee must be paid before your appointment is confirmed.`,premium:`A ${a} reservation fee is required to reserve your appointment time.`}[t]});
  if(inc.cancellation)sec.push({title:"Cancellations",text:`${tc.cancellation} A new booking fee may be required before rebooking.`,short:{soft:`Please give at least ${s.cancellationNotice} hours' notice if you need to cancel or make changes.`,clear:`${s.cancellationNotice} hours' notice is required for cancellations or changes.`,firm:`Cancellations require ${s.cancellationNotice} hours' notice. Late cancellations may result in loss of the booking fee.`,premium:`Changes or cancellations within ${s.cancellationNotice} hours may result in the reservation fee being retained.`}[t]});
  if(inc.noShow){const base=s.noShowRule==="bookingFeeKept"?"your booking fee will be kept and a new fee will be required to rebook.":"you may be required to pay for the missed appointment before rebooking.";const text=s.noShowRule==="bookingFeeKept"?"If you do not show up to your appointment, your booking fee will be kept. A new booking fee will be required to book again.":"If you do not show up to your appointment, you may be required to pay for the missed appointment before booking again.";sec.push({title:"No-Shows",text,short:{soft:`If you are unable to make your appointment, please let us know. If you do not show up, ${base}`,clear:`If you do not attend your appointment, ${base}`,firm:`No-shows will result in ${base} Future bookings may be restricted.`,premium:`Missed appointments without notice will result in ${base}`}[t]});}
  if(inc.lateArrival)sec.push({title:"Late Arrivals",text:`Please arrive on time for your appointment. If you are more than ${s.lateMinutes} minutes late, your appointment may need to be shortened, rescheduled, or cancelled. The full appointment cost may still apply if the service cannot be completed due to lateness.`,short:{soft:`If you are running late, please let us know. Arrivals more than ${s.lateMinutes} minutes late may need to be rescheduled.`,clear:`If you are more than ${s.lateMinutes} minutes late, your appointment may need to be shortened or rescheduled.`,firm:`Arrivals more than ${s.lateMinutes} minutes late may result in a shortened, rescheduled, or cancelled appointment. The full fee may still apply.`,premium:`Late arrivals beyond ${s.lateMinutes} minutes may affect the reserved appointment time and service availability.`}[t]});
  if(inc.rescheduling)sec.push({title:"Rescheduling",text:`Appointments may be rescheduled up to ${rt}, provided enough notice is given. Further changes may require a new booking fee.`,short:{soft:`Appointments can be rescheduled up to ${rt} with enough notice — just get in touch as soon as you can.`,clear:`Appointments may be rescheduled up to ${rt} with enough notice.`,firm:`Appointments may only be rescheduled up to ${rt}. Further changes may require a new booking fee.`,premium:`Appointments may be rescheduled up to ${rt} with appropriate notice. Additional changes may require a new reservation fee.`}[t]});
  if(inc.refunds){const text=s.refundPolicy==="serviceBased"?tc.refund:{premium:"Due to the customised nature of services and appointment preparation, all sales are considered final.",firm:"All sales and services are final."}[t]||"All sales are final unless otherwise stated by the business.";const short={soft:s.refundPolicy==="serviceBased"?"If you have any concerns, please reach out and we will review them together.":"All sales are final. Please get in touch if you have any concerns.",clear:s.refundPolicy==="serviceBased"?"Refunds are not offered for change of mind. Concerns must be raised within the required timeframe.":"All sales are final.",firm:s.refundPolicy==="serviceBased"?"Refunds are not offered. Concerns raised outside the required timeframe may be treated as a new appointment.":"All sales and services are final. No refunds will be issued.",premium:s.refundPolicy==="serviceBased"?"Due to the customised nature of services, refunds are not offered for change of mind.":"Due to the customised nature of services, all sales are considered final."}[t];sec.push({title:"Refunds",text,short});}
  if(inc.sickness)sec.push({title:"Sickness",text:`If you are unwell, please reschedule your appointment with as much notice as possible, ideally at least ${s.sicknessNotice} hours before your appointment. This helps protect the health of the business, other clients, and everyone in the space.`,short:{soft:"If you are feeling unwell, please reach out to reschedule. We appreciate as much notice as possible.",clear:"If you are unwell, please reschedule before attending your appointment.",firm:"Do not attend your appointment if you are unwell. Please reschedule with as much notice as possible.",premium:"If you are unwell, please reschedule your appointment prior to attending."}[t]});
  if(inc.childrenGuests){const ch=s.childrenPolicy==="noChildren"?"Children are not able to attend appointments unless agreed prior. This is for safety, focus, and insurance reasons.":"Please check before bringing children to your appointment, as not all services or appointment spaces are suitable.";const gu=s.extraGuestsPolicy==="noGuests"?"Please attend your appointment alone unless otherwise arranged.":"Extra guests may be allowed by prior arrangement only.";sec.push({title:"Children & Extra Guests",text:`${ch} ${gu}`,short:`${ch} ${gu}`});}
  if(inc.patchTesting&&s.patchTestRequired)sec.push({title:"Patch Testing",text:"Patch testing may be required for selected services or products. If a patch test is required and has not been completed within the correct timeframe, your appointment may need to be rescheduled.",short:{soft:"Patch testing may be needed for some services — please check before booking if you are unsure.",clear:"Patch testing may be required for selected services.",firm:"Patch testing is required for applicable services. Failure to complete a patch test may result in your appointment being rescheduled.",premium:"Patch testing may be required prior to selected services. Please confirm at the time of booking."}[t]});
  if(inc.correctionWork)sec.push({title:"Concerns & Correction Work",text:`If you have a concern with your service, please contact the business within ${s.correctionWindow} hours so it can be assessed. Concerns raised outside this timeframe may be treated as a new appointment or maintenance service.`,short:{soft:`If you have any concerns after your appointment, please reach out within ${s.correctionWindow} hours so we can look into it together.`,clear:`Please raise any service concerns within ${s.correctionWindow} hours of your appointment.`,firm:`Concerns must be raised within ${s.correctionWindow} hours. Issues raised after this time may be treated as a new appointment.`,premium:`Any concerns regarding your service should be raised within ${s.correctionWindow} hours so they can be professionally reviewed.`}[t]});
  if(inc.parkingPolicy){const pk=s.parkingType==="onsite"?"Onsite parking is available for clients. Please allow enough time to park before your appointment, as late arrival due to parking may still fall under the late arrival policy.":"Please note there is no onsite parking available. Clients are responsible for allowing enough time to find parking before their appointment. Late arrival due to parking may still fall under the late arrival policy.";sec.push({title:"Parking",text:`${pk} If you are more than ${s.parkingGraceMinutes} minutes late, your appointment may need to be shortened, rescheduled, or cancelled.`,short:{soft:`${pk} Please allow extra time for parking so we can get started on time.`,clear:pk,firm:`${pk} Late arrival due to parking is still subject to the late arrival policy.`,premium:`${pk} Clients are responsible for allowing sufficient time to park prior to their appointment.`}[t]});}
  const micro=[["foreignFill","Foreign Fills","Foreign fills are assessed on a case-by-case basis. Existing work completed by another artist may need to be removed before a new set or refill can be completed if the current work does not meet the business standards required for safe application or maintenance.","Foreign fills are assessed case-by-case and may require removal before booking."],["retentionPolicy","Retention Results","Retention varies between individuals based on lifestyle, aftercare, skin type, natural lash cycle, products used at home, medications, and ongoing maintenance. Individual retention results cannot be guaranteed.","Retention varies between individuals and cannot be guaranteed."],["phoneUse","Phone Use During Appointments","To help maintain timing, focus, and service quality, phone calls may need to be limited during appointments unless urgent.","Phone calls may need to be limited during appointments unless urgent."],["silentAppointments","Silent Appointments","Silent appointments may be available for clients who prefer a quieter appointment experience. Please advise when booking if this is something you would prefer.","Silent appointments may be available upon request."],["photoConsent","Photography & Content Consent","Photos or videos of completed work may occasionally be taken for portfolio, education, marketing, or social media purposes unless otherwise requested by the client prior to the service.","Photos of completed work may be taken unless otherwise requested."],["runningLatePreviousClient","Running Late Due To Previous Appointments","Occasionally appointments may run behind due to service adjustments, client needs, or unforeseen circumstances. If delays occur, the business will communicate this as soon as possible.","Occasionally appointments may run behind due to previous services."],["depositTransfer","Deposit Transfers","Booking fees or deposits are generally non-transferable outside the allowed rescheduling timeframe unless otherwise approved by the business.","Deposits are generally non-transferable outside approved rescheduling timeframes."],["hennaLongevity","Henna & Hybrid Stain Longevity","Skin stain longevity varies between individuals based on skin type, skincare products, lifestyle, aftercare, oil production, and daily activities. Stain longevity cannot be guaranteed.","Henna and hybrid stain longevity varies between individuals."],["pmuColourRetention","PMU Colour Retention","PMU colour retention varies between individuals based on skin type, undertones, lifestyle, aftercare, medications, sun exposure, healing response, and long-term skin changes. Colour retention cannot be guaranteed.","PMU colour retention varies between individuals and cannot be guaranteed."],["touchUpPricing","Touch-Up Pricing","Touch-up pricing may vary depending on the timeframe since the previous appointment, the amount of work required, retention, and whether the previous work was completed by another artist.","Touch-up pricing may vary depending on timing and work required."],["modelBookings","Model Appointments","Model appointments may be discounted training, portfolio, timing, or educational appointments and may take longer than standard bookings. Specific styling, timing, or outcomes may be limited during model appointments.","Model appointments may differ from standard appointments and may take longer."],["studentCaseStudies","Student Case Studies","Students may be required to complete case studies, submit photos, complete assessments, or provide additional work before certification or course completion requirements are met.","Case studies and assessments may be required before certification is issued."]];
  micro.forEach(([key,title,text,short])=>{if(inc[key])sec.push({title,text,short});});
  if(inc.medicalDisclosure)sec.push({title:"Medical & Contraindications Disclosure",text:"Clients are responsible for disclosing any medical conditions, medications, allergies, skin sensitivities, recent cosmetic procedures, pregnancy, breastfeeding, or contraindications that may affect the safety, suitability, healing, or outcome of the service. Failure to disclose relevant information may affect results and may prevent the service from being performed.",short:"Please disclose medical conditions, medications, allergies, or contraindications before your appointment."});
  if(inc.healingPolicy)sec.push({title:"Healing Results",text:"Healed results vary between individuals based on skin type, lifestyle, aftercare, healing response, retention, and how the area is cared for during healing. Final healed results cannot be guaranteed. Following aftercare instructions is essential to support the best possible healed outcome.",short:"Healed results vary between individuals and cannot be guaranteed."});
  if(inc.touchUpPolicy)sec.push({title:"Touch-Up Appointments",text:`Touch-up appointments may be required once healing has taken place. Recommended touch-ups should be booked within ${s.touchUpWindow} weeks unless otherwise advised. Touch-ups booked outside the recommended timeframe may be treated as a new appointment or priced differently.`,short:`Touch-ups should be booked within ${s.touchUpWindow} weeks unless otherwise advised.`});
  if(inc.trainingDeposit)sec.push({title:"Training Deposits",text:`A non-refundable training deposit of ${money(s.trainingDepositAmount,currency)} is required to secure your place. Your training place is not confirmed until this has been paid. Preparation, resources, scheduling, and student support begin once your place is booked.`,short:`A non-refundable ${money(s.trainingDepositAmount,currency)} training deposit is required to secure your place.`});
  if(inc.trainingPayment)sec.push({title:"Training Payments",text:`Training must be paid in full at least ${s.trainingPaymentDueDays} days before the course date unless otherwise agreed. Full payment must be completed before onboarding, training manuals, course resources, student support access, login details, kits, or training materials are provided.`,short:"Training must be paid in full before onboarding, resources, or training materials are provided."});
  if(inc.trainingRefunds)sec.push({title:"Training Refunds",text:"Due to the preparation, resources, scheduling, digital access, kits, manuals, and educator time involved, training payments are non-refundable. If you are unable to attend, please make contact as soon as possible to discuss available options.",short:"Training payments are non-refundable due to preparation and resources involved."});
  if(inc.trainingCancellation)sec.push({title:"Training Cancellations",text:`Training cancellations require at least ${s.trainingCancellationNotice} days' notice. Cancellations made within this timeframe may result in loss of deposits, payments made, access to resources, or eligibility to transfer to another training date.`,short:`Training cancellations require at least ${s.trainingCancellationNotice} days' notice.`});
  if(inc.trainingRescheduling)sec.push({title:"Training Rescheduling",text:`Training dates may only be rescheduled with at least ${s.trainingRescheduleNotice} days' notice. Last-minute changes may result in loss of the deposit or require a new booking fee before transferring to another date. Training places are limited and dates are prepared in advance.`,short:`Training rescheduling requires at least ${s.trainingRescheduleNotice} days' notice.`});
  if(inc.certificationPolicy)sec.push({title:"Certification",text:"Certificates are issued upon successful completion of the training requirements set by the educator. Certification confirms course completion only and does not replace licensing, qualification requirements, insurance requirements, local regulations, or ongoing competency expectations where applicable.",short:"Certification confirms course completion only and is issued once training requirements are successfully completed."});
  if(inc.payment){const text=s.paymentTiming==="appointmentEnd"?"Payment is due at the end of your appointment before leaving.":"Payment is required before or at the time of service as agreed when booking.";sec.push({title:"Payment",text,short:text});}
  return sec;
}

function formatFullPolicy(intro,sections,businessName,isEducator){
  return [businessName,"Policies & Client Information","────────────────────────────",...(!isEducator?[intro]:[]),...sections.map(s=>`${s.title}\n${s.text}`),"────────────────────────────","Thank you for respecting the time, preparation, and care that goes into every appointment."].join("\n\n");
}

function calculateHealth(settings,included,isEducator){
  const bType=isEducator?"educator":settings.businessType||"beautyLashArtist";
  const selected=Object.entries(included).filter(([,v])=>v).map(([k])=>k);
  const focus=BUSINESS_CATEGORY_FOCUS[bType]||BUSINESS_CATEGORY_FOCUS.beautyLashArtist;
  const cats=focus.map(cat=>{const possible=Object.values(POLICY_WEIGHTS).reduce((t,w)=>t+(w[cat]||0),0);const sel=selected.reduce((t,p)=>t+(POLICY_WEIGHTS[p]?.[cat]||0),0);return{key:cat,label:CATEGORY_LABELS[cat],score:possible?Math.round((sel/possible)*100):0};});
  return{score:Math.round(cats.reduce((t,c)=>t+c.score,0)/cats.length),categoryScores:cats};
}

// ─── PLAYBOOK COMPONENTS ──────────────────────────────────────────────────────

function ChapterBlock({block}){
  if(block.type==="p")return <p className="chapterP">{block.text}</p>;
  if(block.type==="note")return <div className="chapterNote"><span>Haus of M</span>{block.text}</div>;
  if(block.type==="reflection")return(<div className="chapterReflection"><div className="chapterReflectionLabel">Reflection</div>{block.items.map((item,i)=><div key={i} className="chapterReflectionItem">— {item}</div>)}</div>);
  if(block.type==="compare")return(<div className="chapterCompare">{block.title&&<div className="chapterCompareTitle">{block.title}</div>}{block.pairs.map((p,i)=>(<div key={i} className="chapterComparePair"><div className="chapterCompareWeak"><span>Weaker</span>{p.weak}</div><div className="chapterCompareArrow">→</div><div className="chapterCompareStrong"><span>Stronger</span>{p.strong}</div></div>))}</div>);
  if(block.type==="table")return(<div className="chapterTableWrap"><table className="chapterTable"><thead><tr>{block.headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{block.rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div>);
  if(block.type==="tones")return(<div className="chapterTones">{block.items.map(t=>(<div key={t.tone} className="chapterToneCard"><div className="chapterToneLabel">{t.tone}</div><p>{t.desc}</p><div className="chapterToneExample">"{t.example}"</div></div>))}</div>);
  if(block.type==="scripts")return(<div className="chapterScripts"><div className="chapterScriptsTitle">{block.title}</div>{block.items.map((s,i)=>(<div key={i} className="chapterScript"><div className="chapterScriptSituation">{s.situation}</div><div className="chapterScriptText">"{s.script}"</div></div>))}</div>);
  if(block.type==="reframe")return(<div className="chapterReframe">{block.title&&<div className="chapterReframeTitle">{block.title}</div>}{block.pairs.map((p,i)=>(<div key={i} className="chapterReframePair"><div className="chapterReframeOld">"{p.old}"</div><div className="chapterReframeArrow">→</div><div className="chapterReframeNew">"{p.neww}"</div></div>))}</div>);
  if(block.type==="bullets")return(<div className="chapterBullets"><div className="chapterBulletsTitle">{block.title}</div><ul>{block.items.map((item,i)=><li key={i}>{item}</li>)}</ul></div>);
  if(block.type==="steps")return(<div className="chapterSteps">{block.items.map(s=>(<div key={s.num} className="chapterStep"><div className="chapterStepNum">{s.num}</div><div><strong>{s.title}</strong><p>{s.desc}</p></div></div>))}</div>);
  return null;
}

const SECTIONS=[
  {label:"Foundation",ids:["intro",1,2,3]},
  {label:"Enforcement",ids:[4,5,6]},
  {label:"Build",ids:[7,"transition"]},
  {label:"Real Situations",ids:["difficult","social","offboarding","pricing","reset"]},
  {label:"Operations",ids:["aftercare","automation","medical","seasonal"]},
  {label:"Close",ids:["final"]},
];

function scrollChapterTop(){
  window.scrollTo({top:0,behavior:"smooth"});
  // Also scroll the page content container
  const el=document.querySelector(".pageContent");
  if(el)el.scrollTo({top:0,behavior:"smooth"});
}

function PlaybookView({onGoToBuilder}){
  const [activeChapter,setActiveChapter]=useState(null);

  const goToChapter=(idx)=>{
    setActiveChapter(idx);
    scrollChapterTop();
  };

  if(activeChapter!==null){
    const ch=CHAPTERS[activeChapter];
    const hasPrev=activeChapter>0;
    const hasNext=activeChapter<CHAPTERS.length-1;
    const NavButtons=({className=""})=>(
      <div className={`chapterNav ${className}`}>
        {hasPrev
          ?<button onClick={()=>goToChapter(activeChapter-1)}>← {CHAPTERS[activeChapter-1].title}</button>
          :<span/>}
        {hasNext
          ?<button onClick={()=>goToChapter(activeChapter+1)}>{CHAPTERS[activeChapter+1].title} →</button>
          :<span/>}
      </div>
    );
    return(
      <div className="chapterView">
        <div className="chapterTopBar">
          <button className="chapterBack" onClick={()=>setActiveChapter(null)}>← All chapters</button>
          <NavButtons className="chapterNav--top"/>
        </div>
        <div className="chapterHeader"><span className="chapterNum">{ch.num}</span><span className="chapterTag">{ch.tag}</span></div>
        <h1 className="chapterTitle">{ch.title}</h1>
        <p className="chapterIntro">{ch.intro}</p>
        <div className="chapterBody">{ch.body.map((block,i)=><ChapterBlock key={i} block={block}/>)}</div>
        {ch.builderLink&&<button className={`chapterBuilderBtn ${ch.builderLink.primary?"chapterBuilderBtn--primary":""}`} onClick={()=>onGoToBuilder(ch.builderLink.highlight)}>{ch.builderLink.label} →</button>}
        <NavButtons className="chapterNav--bottom"/>
      </div>
    );
  }

  return(
    <div className="playbookView">
      <div className="playbookHero">
        <p className="playbookEyebrow">The Policy Playbook</p>
        <h1 className="playbookTitle">Clear boundaries for beauty professionals.</h1>
        <p className="playbookSub">skill. standard. self-trust.</p>
        <p className="playbookDesc">A complete boundary and policy guide for beauty professionals — covering why policies matter, how wording shapes perception, how to enforce confidently, and how to build policies that actually fit your business.</p>
      </div>
      {SECTIONS.map(section=>{
        const sectionChapters=section.ids.map(id=>({ch:CHAPTERS.find(c=>c.id===id),idx:CHAPTERS.findIndex(c=>c.id===id)})).filter(x=>x.ch);
        return(
          <div key={section.label} className="playbookSection">
            <div className="playbookSectionLabel">{section.label}</div>
            <div className="chapterGrid">
              {sectionChapters.map(({ch,idx})=>(
                <button key={ch.id} className="chapterCard" onClick={()=>goToChapter(idx)}>
                  <div className="chapterCardTop"><span className="chapterCardNum">{ch.num}</span><span className="chapterCardTag">{ch.tag}</span></div>
                  <div className="chapterCardTitle">{ch.title}</div>
                  <div className="chapterCardIntro">{ch.intro}</div>
                  <div className="chapterCardCta">{ch.id==="final"?"Read closing ✦":"Read chapter →"}</div>
                </button>
              ))}
            </div>
          </div>
        );
      })}
      <button className="playbookBuilderBtn" onClick={()=>onGoToBuilder()}>Ready to build your policies? Open the Builder →</button>
    </div>
  );
}

// ─── BUILDER COMPONENTS ───────────────────────────────────────────────────────

function PolicyCheck({policyKey,included,settings,updateIncluded,updateSetting}){
  const checked=!!included[policyKey];
  const fields=POLICY_SETTINGS[policyKey]||[];
  return(
    <div className={`policyItem ${checked?"policyItem--on":""}`}>
      <label className="policyCheck">
        <input type="checkbox" checked={checked} onChange={e=>updateIncluded(policyKey,e.target.checked)}/>
        <span className="policyCheckBox"/>
        <div className="policyLabelGroup">
          <span className="policyLabel">{POLICY_LABELS[policyKey]}</span>
          {POLICY_NOTES[policyKey]&&<span className="policyNote">{POLICY_NOTES[policyKey]}</span>}
        </div>
      </label>
      {checked&&fields.length>0&&(
        <div className="policyInlineFields">
          {fields.map(f=>f.type==="select"?(
            <label key={f.key} className="inlineField"><span>{f.label}</span><select value={settings[f.key]} onChange={e=>updateSetting(f.key,e.target.value)}>{f.options.map(([val,lab])=><option key={val} value={val}>{lab}</option>)}</select></label>
          ):(
            <label key={f.key} className="inlineField"><span>{f.label}</span><input type="text" inputMode="numeric" value={settings[f.key]} onChange={e=>{const v=e.target.value.split("").filter(c=>c>="0"&&c<="9").join("");updateSetting(f.key,v===""?0:Number(v));}} onFocus={e=>e.target.select()}/></label>
          ))}
        </div>
      )}
    </div>
  );
}

function HealthIndicator({score}){
  const color=score>=80?"#7ee7d8":score>=50?"#f5c842":"#ff7c7c";
  const label=score>=80?"Strong":score>=50?"Building":"Light";
  return(<div className="healthIndicator"><div className="healthIndicatorBar"><div className="healthIndicatorFill" style={{width:`${score}%`,background:color}}/></div><span className="healthIndicatorLabel" style={{color}}>{label}</span></div>);
}

function FormattedOutput({text,format}){
  if(format==="message")return <div className="messagePreview"><p>{text}</p></div>;
  return(
    <div className={`formattedOutput ${format==="instagram"?"instagramStyle":""}`}>
      {text.split("\n\n").map((block,i)=>{
        const lines=block.split("\n").filter(Boolean);const first=lines[0]||"";const rest=lines.slice(1).join("\n");
        const isDivider=first.includes("────");const isTitle=first===first.toUpperCase()&&first.length<60&&!isDivider;
        if(isDivider)return <div key={i} className="outputDivider"/>;
        return(<div key={i} className={isTitle?"outputBlock titleBlock":"outputBlock"}>{isTitle?<h3>{first}</h3>:<strong>{first}</strong>}{rest?<p>{rest}</p>:null}</div>);
      })}
    </div>
  );
}

function BuilderView({initialHighlight}){
  const [currency,setCurrency]=useState("NZD");
  const [isEducator,setIsEducator]=useState(false);
  const [businessType,setBusinessType]=useState("beautyLashArtist");
  const [settings,setSettings]=useState(DEFAULT_SETTINGS);
  const [included,setIncluded]=useState(DEFAULT_INCLUDED);
  const [outputFormat,setOutputFormat]=useState(initialHighlight==="message"?"message":"full");
  const [presetsOpen,setPresetsOpen]=useState(false);
  const [presetName,setPresetName]=useState("My Policy Setup");
  const [savedPresets,setSavedPresets]=useState([]);
  const [copyStatus,setCopyStatus]=useState("");
  const [mobileTab,setMobileTab]=useState("build");

  useEffect(()=>{
    try{const stored=localStorage.getItem("hausOfMPresets_v3");if(stored)setSavedPresets(JSON.parse(stored));}catch{}
  },[]);

  const updateSetting=(k,v)=>setSettings(p=>({...p,[k]:v}));
  const updateIncluded=(k,v)=>setIncluded(p=>({...p,[k]:v}));
  const clearAll=()=>setIncluded(isEducator?Object.fromEntries(Object.keys(DEFAULT_INCLUDED).map(k=>[k,false])):DEFAULT_INCLUDED);
  const switchMode=(edu)=>{setIsEducator(edu);setIncluded(Object.fromEntries(Object.keys(DEFAULT_INCLUDED).map(k=>[k,false])));if(!edu)setBusinessType("beautyLashArtist");};
  const applyRecommended=()=>{const keys=isEducator?EDUCATOR_POLICIES.recommended:(BUSINESS_POLICIES[businessType]?.recommended||[]);setIncluded(p=>{const u={...p};keys.forEach(k=>{u[k]=true;});return u;});};
  const savePresetsToStorage=(p)=>{setSavedPresets(p);try{localStorage.setItem("hausOfMPresets_v3",JSON.stringify(p));}catch{}};
  const savePreset=()=>{const name=presetName.trim()||"My Setup";const preset={id:Date.now().toString(),name,settings,included,isEducator,businessType,createdAt:new Date().toLocaleDateString("en-NZ")};savePresetsToStorage([preset,...savedPresets]);setCopyStatus("Saved!");setTimeout(()=>setCopyStatus(""),2000);};
  const loadPreset=p=>{setSettings({...DEFAULT_SETTINGS,...p.settings});setIncluded({...DEFAULT_INCLUDED,...p.included});if(p.isEducator!==undefined)setIsEducator(p.isEducator);if(p.businessType)setBusinessType(p.businessType);};
  const deletePreset=id=>savePresetsToStorage(savedPresets.filter(p=>p.id!==id));

  const settingsWithType=useMemo(()=>({...settings,businessType:isEducator?"educator":businessType}),[settings,isEducator,businessType]);
  const toneContent=useMemo(()=>createToneContent(settingsWithType,currency),[settingsWithType,currency]);
  const policySections=useMemo(()=>createPolicySections(settingsWithType,included,currency),[settingsWithType,included,currency]);
  const fullPolicy=useMemo(()=>formatFullPolicy(toneContent.intro,policySections,settings.businessName,isEducator),[toneContent.intro,policySections,settings.businessName,isEducator]);
  const instagramPolicy=useMemo(()=>policySections.map(s=>`${s.title}\n${s.short}`).join("\n\n"),[policySections]);
  const confirmationMessage=useMemo(()=>{
    const tone=settings.tone;
    const start={soft:`Hi lovely, your appointment with ${settings.businessName} is officially booked.`,clear:`Your appointment with ${settings.businessName} is confirmed.`,firm:`Your appointment with ${settings.businessName} is confirmed. Please read the booking terms below.`,premium:`Your appointment with ${settings.businessName} has been reserved.`}[tone];
    const msgs=[];
    if(included.bookingFee)msgs.push(tone==="premium"?`Your ${money(settings.bookingFeeAmount,currency)} reservation fee has been received.`:`Your ${money(settings.bookingFeeAmount,currency)} booking fee has been received.`);
    if(included.cancellation)msgs.push(tone==="soft"?`Please give at least ${settings.cancellationNotice} hours' notice if you need to make any changes.`:`A ${settings.cancellationNotice}-hour cancellation policy applies for changes or cancellations.`);
    if(included.lateArrival)msgs.push(tone==="premium"?`Arriving late may affect the reserved appointment time.`:`If you are more than ${settings.lateMinutes} minutes late, your appointment may need to be shortened or rescheduled.`);
    if(included.noShow)msgs.push(tone==="firm"?`Missed appointments may require payment before another booking is accepted.`:`Missed appointments may require payment before rebooking.`);
    if(included.sickness)msgs.push(tone==="soft"?`If you are unwell, please get in touch to reschedule before attending.`:`If you are unwell, please reschedule before attending your appointment.`);
    const closing={soft:`Thank you, and I look forward to seeing you soon.`,clear:`Thank you for respecting the time and preparation that goes into your appointment.`,firm:`Thank you for respecting the booking policy and appointment time.`,premium:`Thank you for respecting the time, preparation, and care reserved for your appointment.`}[tone];
    return `${start}\n${msgs.join("\n")}\n${closing}`;
  },[settings,included,currency]);

  const {score}=useMemo(()=>calculateHealth(settingsWithType,included,isEducator),[settingsWithType,included,isEducator]);
  const selectedCount=Object.values(included).filter(Boolean).length;
  const activeGroups=isEducator?EDUCATOR_POLICIES.groups:(BUSINESS_POLICIES[businessType]?.groups||[]);
  const outputText=outputFormat==="full"?fullPolicy:outputFormat==="instagram"?instagramPolicy:confirmationMessage;

  const handleCopy=async()=>{setCopyStatus("");try{await doClipboard(outputText);setCopyStatus("Copied!");setTimeout(()=>setCopyStatus(""),2000);}catch{setCopyStatus("Select & copy manually.");}};

  const handleExportPDF=()=>{
    const formatLabel=outputFormat==="instagram"?"Instagram Version":outputFormat==="message"?"Client Booking Message":"Business Policies";
    const toneLabel=TONE_PROFILES[settings.tone]?.label||"Clear";
    const date=new Date().toLocaleDateString("en-NZ");
    const nl=String.fromCharCode(10);
    const sectionsHtml=outputFormat==="full"||outputFormat==="instagram"
      ?policySections.map(s=>{
          const body=outputFormat==="instagram"?String(s.short||""):String(s.text||"");
          return "<div class='ps'><div class='pt'>"+s.title.toUpperCase()+"</div><div class='pb'>"+body.split(nl).join("<br/>")+"</div></div>";
        }).join("")
      :"<div class='ps'><div class='pb' style='white-space:pre-wrap'>"+confirmationMessage+"</div></div>";
    const css=[
      "*{box-sizing:border-box;margin:0;padding:0;}",
      "body{font-family:Georgia,serif;font-size:11pt;color:#111;line-height:1.6;padding:18mm;}",
      "h1{font-size:20pt;font-weight:400;margin-bottom:6pt;}",
      ".meta{font-family:Arial,sans-serif;font-size:8pt;color:#888;border-bottom:1pt solid #ddd;padding-bottom:10pt;margin-bottom:18pt;}",
      ".ps{margin-bottom:16pt;padding-bottom:16pt;border-bottom:1pt solid #eee;}",
      ".ps:last-child{border-bottom:none;}",
      ".pt{font-family:Arial,sans-serif;font-size:7.5pt;font-weight:700;text-transform:uppercase;letter-spacing:1pt;color:#555;margin-bottom:5pt;}",
      ".pb{font-size:10.5pt;line-height:1.75;}",
      ".footer{font-family:Arial,sans-serif;font-size:7pt;color:#bbb;border-top:1pt solid #eee;padding-top:8pt;margin-top:20pt;}"
    ].join("");
    const fullHtml=[
      "<!DOCTYPE html><html><head><meta charset='utf-8'><style>",
      css,
      "</style></head><body>",
      "<h1>"+settings.businessName+"</h1>",
      "<div class='meta'>"+formatLabel+" &middot; "+toneLabel+" tone &middot; "+date+"</div>",
      sectionsHtml,
      "<div class='footer'>Haus of M Policy Builder &mdash; Business education tool. Not legal advice.</div>",
      "</body></html>"
    ].join("");
    try{
      const encoded="data:text/html;charset=utf-8,"+encodeURIComponent(fullHtml);
      const a=document.createElement("a");
      a.href=encoded;
      a.download=settings.businessName.toLowerCase().split("").map(c=>(c>="a"&&c<="z")||(c>="0"&&c<="9")?c:"_").join("")+"_policies.html";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setCopyStatus("Downloaded!");
      setTimeout(()=>setCopyStatus(""),3000);
    }catch(e){
      console.error("Export failed:",e);
      setCopyStatus("Copy text instead");
      setTimeout(()=>setCopyStatus(""),3000);
    }
  };

  return(
    <div className="builderRoot">
      <div className="builderTopBar">
        <div className="topBarRow topBarRow--identity">
          <div className="modeToggle">
            <button className={!isEducator?"active":""} onClick={()=>switchMode(false)}>Artist</button>
            <button className={isEducator?"active":""} onClick={()=>switchMode(true)}>Educator</button>
          </div>
          {!isEducator&&(<select className="topBarSelect topBarType" value={businessType} onChange={e=>setBusinessType(e.target.value)}>{Object.entries(BUSINESS_POLICIES).map(([k,v])=><option key={k} value={k}>{v.label}</option>)}</select>)}
          <select className="topBarSelect topBarCurrency" value={currency} onChange={e=>setCurrency(e.target.value)}>{["NZD","AUD","USD","GBP"].map(c=><option key={c} value={c}>{c}</option>)}</select>
        </div>
        <div className="topBarRow topBarRow--name">
          <input className="topBarInput topBarInputFull" value={settings.businessName} onChange={e=>updateSetting("businessName",e.target.value)} placeholder="Business name"/>
        </div>
        <div className="topBarRow topBarRow--tone">
          <div className="toneGroupLabelWrap">
            <span className="toneGroupLabel">Business Tone</span>
            <span className="toneGroupHint">Controls the language style of all generated policy output</span>
          </div>
          <div className="toneToggle">
            {Object.entries(TONE_PROFILES).map(([k,v])=>(<button key={k} className={settings.tone===k?"active":""} onClick={()=>updateSetting("tone",k)} title={v.desc}>{v.label}</button>))}
          </div>
        </div>
      </div>

      <div className={`mainSplit ${mobileTab==="output"?"mainSplit--output":""}`}>
        <aside className="builderPanel">
          <div className="builderHeader">
            <div className="builderCountRow">
              <span className="builderCount">{selectedCount} policies selected</span>
              {selectedCount>0&&<button className="clearBtn" onClick={clearAll}>Clear all</button>}
            </div>
            <div className="builderApplyRow">
              <button className="applyBtn" onClick={applyRecommended}>Apply recommended</button>
              <span className="applyBtnHint">{(isEducator?EDUCATOR_POLICIES.recommended:(BUSINESS_POLICIES[businessType]?.recommended||[])).map(k=>POLICY_LABELS[k]).join(" · ")}</span>
            </div>
            <div className="builderPresetsRow">
              <button className="presetsBtn" onClick={()=>setPresetsOpen(o=>!o)}>
                Save / load policy set {savedPresets.length>0?<span className="presetCount">{savedPresets.length}</span>:null}
                <span className="presetsCaret">{presetsOpen?"▲":"▼"}</span>
              </button>
            </div>
            {presetsOpen&&(
              <div className="presetsInline">
                <div className="presetSave">
                  <input value={presetName} onChange={e=>setPresetName(e.target.value)} placeholder="Name this set — e.g. PMU setup, busy season…"/>
                  <button onClick={savePreset}>Save</button>
                </div>
                {savedPresets.length===0&&<p className="presetEmpty">No saved sets yet. Tick your policies and save a set to reload them anytime.</p>}
                {savedPresets.map(p=>(
                  <div key={p.id} className="presetItem">
                    <div className="presetItemInfo">
                      <strong>{p.name}</strong>
                      <span>{Object.values(p.included||{}).filter(Boolean).length} policies · {p.createdAt}</span>
                    </div>
                    <div className="presetActions">
                      <button onClick={()=>loadPreset(p)}>Load</button>
                      <button className="presetDelete" onClick={()=>deletePreset(p.id)}>✕</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div className="policyGroups">
            {activeGroups.map(group=>(
              <div key={group.title} className="policyGroup">
                <h3>{group.title}</h3>
                {group.keys.map(key=>(<PolicyCheck key={key} policyKey={key} included={included} settings={settings} updateIncluded={updateIncluded} updateSetting={updateSetting}/>))}
              </div>
            ))}
          </div>

        </aside>

        <section className="outputPanel">
          <div className="outputHeader">
            <div className="outputFormatToggle">
              {[["full","Full Policy"],["instagram","Instagram"],["message","Client Message"]].map(([k,l])=>(<button key={k} className={outputFormat===k?"active":""} onClick={()=>setOutputFormat(k)}>{l}</button>))}
            </div>
            <div className="outputHeaderRight">
              <HealthIndicator score={score}/>
              <button className="copyBtn" onClick={handleCopy}>{copyStatus||"Copy"}</button>
              {selectedCount>0&&<button className="copyBtn exportBtn" onClick={handleExportPDF} title="Download as PDF">↓ Export</button>}
            </div>
          </div>
          <div className="outputContent">
            {selectedCount===0?(
              <div className="outputEmpty"><p>No policies selected yet.</p><p>Tick policies on the left to see your output here.</p></div>
            ):(
              <FormattedOutput text={outputText} format={outputFormat}/>
            )}
          </div>
          <div className="outputFooterRow">
            <p className="outputDisclaimer">Business education tool. Not legal advice.</p>
            <button className="backToTopBtn" onClick={()=>window.scrollTo({top:0,behavior:"smooth"})}>↑ Top</button>
          </div>
        </section>
      </div>

      <nav className="mobileNav">
        <button className={mobileTab==="build"?"active":""} onClick={()=>setMobileTab("build")}><span className="mobileNavIcon">☰</span><span>Build</span></button>
        <button className={mobileTab==="output"?"active":""} onClick={()=>{setMobileTab("output");window.scrollTo({top:0,behavior:"smooth"});}}><span className="mobileNavIcon">◎</span><span>Output{selectedCount>0?` (${selectedCount})`:""}</span></button>
      </nav>
    </div>
  );
}

// ─── ROOT ─────────────────────────────────────────────────────────────────────

export default function HausOfMApp(){
  const [session, setSession] = useState(null); // {token, user}
  const [accessOk, setAccessOk] = useState(false);
  const [checking, setChecking] = useState(true);
  const [noAccess, setNoAccess] = useState(false);

  // On mount: restore session from localStorage
  useEffect(()=>{
    const stored = localStorage.getItem("hom_session");
    if(stored){
      try{
        const s = JSON.parse(stored);
        setSession(s);
        verifyAccess(s);
      } catch { setChecking(false); }
    } else { setChecking(false); }
  },[]);

  const verifyAccess = async(s)=>{
    setChecking(true);
    try{
      // Verify token still valid
      const user = await sb.getUser(s.token);
      if(user.error){ logout(); return; }
      // Check product access
      const ok = await sb.checkAccess(s.token, user.id);
      if(ok){ setAccessOk(true); setNoAccess(false); }
      else { setNoAccess(true); setAccessOk(false); }
    } catch { setNoAccess(true); }
    setChecking(false);
  };

  const handleAuth = (token, user)=>{
    const s = {token, user};
    setSession(s);
    localStorage.setItem("hom_session", JSON.stringify(s));
    verifyAccess(s);
  };

  const logout = ()=>{
    if(session) sb.signOut(session.token);
    setSession(null);
    setAccessOk(false);
    setNoAccess(false);
    setChecking(false);
    localStorage.removeItem("hom_session");
  };

  if(checking) return(
    <div style={{minHeight:"100vh",background:"#080808",display:"flex",alignItems:"center",justifyContent:"center"}}>
      <style>{"body{background:#080808;margin:0;}"}</style>
      <div style={{fontFamily:"Georgia,serif",color:"rgba(255,255,255,.4)",fontSize:"14px",letterSpacing:".1em"}}>Loading…</div>
    </div>
  );

  if(!session) return <AuthScreen onAuth={handleAuth}/>;

  if(noAccess) return(
    <div style={{minHeight:"100vh",background:"#080808",display:"flex",alignItems:"center",justifyContent:"center",padding:"24px"}}>
      <style>{"body{background:#080808;margin:0;font-family:Inter,sans-serif;}"}</style>
      <div style={{maxWidth:"380px",textAlign:"center"}}>
        <div style={{fontFamily:"Georgia,serif",fontSize:"28px",color:"#f8f8f8",marginBottom:"16px"}}>M</div>
        <h2 style={{fontFamily:"Georgia,serif",fontWeight:400,fontSize:"18px",color:"#f0f0f0",marginBottom:"12px"}}>Access not found</h2>
        <p style={{color:"rgba(255,255,255,.5)",fontSize:"13px",lineHeight:"1.7",marginBottom:"24px"}}>Your account does not have access to the Policy Builder. If you have purchased, please contact us and we will sort it out.</p>
        <button onClick={logout} style={{background:"none",border:"1px solid rgba(255,255,255,.2)",borderRadius:"999px",color:"rgba(255,255,255,.6)",padding:"10px 24px",cursor:"pointer",fontSize:"12px",textTransform:"uppercase",letterSpacing:".1em"}}>Sign out</button>
      </div>
    </div>
  );

  // Passed auth — render the full app with sign out in nav
  const userEmail = session?.user?.email || "";
  // eslint-disable-next-line no-unused-vars
  const _logout = logout; // expose for nav

  
  const [activeSection,setActiveSection]=useState("home");
  const [builderHighlight,setBuilderHighlight]=useState(null);

  const goToBuilder=(highlight)=>{setBuilderHighlight(highlight||null);setActiveSection("builder");window.scrollTo({top:0,behavior:"smooth"});};

  return(
    <div className="app">
      <style>{CSS}</style>
      <div className="monogram" aria-hidden="true"><img src={LOGO_SRC} alt="" className="monogramImg"/></div>

      <nav className="globalNav">
        <button className="globalNavLogo" onClick={()=>setActiveSection("home")}>
          <div className="hausLockup">
            <div className="hausLockupTop">HAUS</div>
            <div className="hausLockupMiddle"><span></span><em>OF</em><span></span></div>
            <div className="hausLockupBottom">M</div>
            <div className="hausLockupSub">Beauty Business Tools</div>
          </div>
        </button>
        <div className="globalNavLinks">
          <button className={activeSection==="playbook"?"active":""} onClick={()=>setActiveSection("playbook")}>Playbook</button>
          <button className={activeSection==="builder"?"active":""} onClick={()=>goToBuilder()}>Policy Builder</button>
          <button className="navSignOut" onClick={logout} title={userEmail}>Sign out</button>
        </div>
      </nav>

      {activeSection==="home"&&(
        <div className="homePage">
          <div className="homeHero">
            <p className="homeEyebrow">skill. standard. self-trust.</p>
            <h1 className="homeTitle">Professional boundaries for beauty professionals.</h1>
            <p className="homeDesc">Learn why policies matter, understand how wording shapes perception, then build policies that actually fit your business — all in one place.</p>
            <div className="homeCtas">
              <button className="homeCta homeCta--primary" onClick={()=>setActiveSection("playbook")}>Read the Playbook</button>
              <button className="homeCta homeCta--secondary" onClick={()=>goToBuilder()}>Open Policy Builder</button>
            </div>
          </div>
          <div className="homeFeatures">
            <div className="homeFeature"><div className="homeFeatureNum">19</div><div className="homeFeatureLabel">Chapters covering everything from why policies matter to booking systems, promotions, medical disclosures, and retaining clients</div></div>
            <div className="homeFeature"><div className="homeFeatureNum">30+</div><div className="homeFeatureLabel">Policies you can mix, match, and customise to fit your exact business model</div></div>
            <div className="homeFeature"><div className="homeFeatureNum">4</div><div className="homeFeatureLabel">Tone styles — soft, clear, firm, and premium — so your policies sound like your brand</div></div>
          </div>
          <div className="homeQuote">
            <blockquote>"Policies are not punishment. They are communication."</blockquote>
            <cite>— Haus of M Policy Playbook</cite>
          </div>
        </div>
      )}

      {activeSection==="playbook"&&(<div className="pageContent"><PlaybookView onGoToBuilder={goToBuilder}/></div>)}
      {activeSection==="builder"&&(<BuilderView initialHighlight={builderHighlight}/>)}

      <footer className="footer"><strong>Haus of M</strong> © 2026. Licensed for personal business use only. Not for resale, redistribution, or teaching as your own.</footer>
    </div>
  );
}

